script:
{% comment %}
  Out-of-stock lifecycle:
  1. An active product with no sellable variant gets the out-of-stock tag, and the time is
     recorded in the mechanic.out_of_stock_since metafield (hourly scan).
  2. If it is still not sellable after the configured number of days, it is set to Draft or
     Unlisted, and the time is recorded in mechanic.out_of_stock_hidden_at (hourly scan).
  3. When a tagged product is sellable again, the tag is removed. If this task hid it during
     the current out-of-stock spell, it is set back to Active. Stock updates trigger this right
     away; the hourly scan catches anything missed.
  Products are never deleted. Archived products, drafts this task did not create, and products
  someone re-activated by hand are left alone.
{% endcomment %}

{% assign out_of_stock_tag = options.out_of_stock_tag__required %}
{% assign never_hide_tag = options.never_hide_products_with_this_tag %}
{% assign days_before_hiding = options.days_before_hiding__number_required %}
{% assign hide_as = options.hide_as__select_o1_draft_o2_unlisted %}
{% assign test_mode = options.test_mode__boolean %}

{% assign hide_status = "DRAFT" %}
{% if hide_as == "unlisted" %}
  {% assign hide_status = "UNLISTED" %}
{% endif %}

{% assign out_of_stock_tag_downcase = out_of_stock_tag | downcase %}
{% assign never_hide_tag_downcase = never_hide_tag | downcase %}
{% assign current_time = "now" | date: "%FT%T%z" %}
{% assign now_s = "now" | date: "%s" | times: 1 %}
{% assign hide_after_s = days_before_hiding | times: 86400 %}
{% assign long_ago_s = now_s | minus: hide_after_s | minus: 86400 %}
{% assign yesterday_s = now_s | minus: 86400 %}

{% comment %}
  -- stock is read from the variants themselves (not product.totalInventory, which lags behind inventory updates)
{% endcomment %}

{% capture product_fields %}
  id
  title
  status
  tags
  variantsCount {
    count
  }
  variants(first: 5) {
    nodes {
      inventoryQuantity
      inventoryPolicy
      inventoryItem {
        tracked
      }
    }
  }
  since: metafield(namespace: "mechanic", key: "out_of_stock_since") {
    value
  }
  hiddenAt: metafield(namespace: "mechanic", key: "out_of_stock_hidden_at") {
    value
  }
{% endcapture %}

{% assign products = array %}
{% assign allowed_steps = "restore,untag,tag,hide" | split: "," %}

{% if event.topic == "shopify/inventory_levels/update" %}
  {% comment %}
    -- a stock update only brings products back; tagging and hiding wait for the hourly scan
  {% endcomment %}

  {% assign allowed_steps = "restore,untag" | split: "," %}

  {% if inventory_level.available > 0 or event.preview %}
    {% capture query %}
      query {
        inventoryLevel(id: {{ inventory_level.admin_graphql_api_id | json }}) {
          item {
            variants(first: 1) {
              nodes {
                product {
                  {{ product_fields }}
                }
              }
            }
          }
        }
      }
    {% endcapture %}

    {% assign result = query | shopify %}

    {% if event.preview %}
      {% capture result_json %}
        {
          "data": {
            "inventoryLevel": {
              "item": {
                "variants": {
                  "nodes": [
                    {
                      "product": {
                        "id": "gid://shopify/Product/3456789012",
                        "title": "Hidden, now back in stock",
                        "status": {{ hide_status | json }},
                        "tags": ["Lustre", {{ out_of_stock_tag | json }}],
                        "variantsCount": { "count": 1 },
                        "variants": { "nodes": [{ "inventoryQuantity": 3, "inventoryPolicy": "DENY", "inventoryItem": { "tracked": true } }] },
                        "since": { "value": {{ long_ago_s | append: "" | json }} },
                        "hiddenAt": { "value": {{ yesterday_s | append: "" | json }} }
                      }
                    }
                  ]
                }
              }
            }
          }
        }
      {% endcapture %}

      {% assign result = result_json | parse_json %}
    {% endif %}

    {% assign changed_product = result.data.inventoryLevel.item.variants.nodes.first.product %}

    {% if changed_product %}
      {% assign products = products | push: changed_product %}
    {% endif %}
  {% endif %}

{% elsif event.topic contains "mechanic/scheduler/" or event.topic == "mechanic/user/trigger" %}
  {% comment %}
    -- if most of the catalog suddenly reads as out of stock, the stock sync is more likely broken than the shelves empty
  {% endcomment %}

  {% capture query %}
    query {
      active: productsCount(query: "status:active", limit: null) {
        count
      }
      outOfStock: productsCount(query: "status:active AND inventory_total:<=0", limit: null) {
        count
      }
    }
  {% endcapture %}

  {% assign result = query | shopify %}

  {% if event.preview %}
    {% assign result = '{"data":{"active":{"count":100},"outOfStock":{"count":40}}}' | parse_json %}
  {% endif %}

  {% assign out_of_stock_percent = 0 %}

  {% if result.data.active.count > 0 %}
    {% assign out_of_stock_percent = result.data.outOfStock.count | times: 100 | divided_by: result.data.active.count %}
  {% endif %}

  {% if out_of_stock_percent > 70 %}
    {% error
      message: "More than 70% of active products look out of stock, so the scan changed nothing. Check the stock sync, then run the task again.",
      active_products: result.data.active.count,
      out_of_stock_products: result.data.outOfStock.count
    %}

    {% break %}
  {% endif %}

  {% comment %}
    -- one scan: active products without stock, plus every product carrying the tag (any status)
  {% endcomment %}

  {%- capture search_query -%}
    (status:active AND inventory_total:<=0) OR tag:{{ out_of_stock_tag | json }}
  {%- endcapture -%}

  {% assign cursor = nil %}

  {% for n in (1..200) %}
    {% capture query %}
      query {
        products(
          first: 50
          after: {{ cursor | json }}
          query: {{ search_query | json }}
        ) {
          pageInfo {
            hasNextPage
            endCursor
          }
          nodes {
            {{ product_fields }}
          }
        }
      }
    {% endcapture %}

    {% assign result = query | shopify %}

    {% if event.preview %}
      {% capture result_json %}
        {
          "data": {
            "products": {
              "pageInfo": {
                "hasNextPage": false,
                "endCursor": null
              },
              "nodes": [
                {
                  "id": "gid://shopify/Product/1234567890",
                  "title": "Newly out of stock",
                  "status": "ACTIVE",
                  "tags": ["Lustre"],
                  "variantsCount": { "count": 1 },
                  "variants": { "nodes": [{ "inventoryQuantity": 0, "inventoryPolicy": "DENY", "inventoryItem": { "tracked": true } }] },
                  "since": null,
                  "hiddenAt": null
                },
                {
                  "id": "gid://shopify/Product/2345678901",
                  "title": "Out of stock for too long",
                  "status": "ACTIVE",
                  "tags": ["Lustre", {{ out_of_stock_tag | json }}],
                  "variantsCount": { "count": 1 },
                  "variants": { "nodes": [{ "inventoryQuantity": 0, "inventoryPolicy": "DENY", "inventoryItem": { "tracked": true } }] },
                  "since": { "value": {{ long_ago_s | append: "" | json }} },
                  "hiddenAt": null
                },
                {
                  "id": "gid://shopify/Product/3456789012",
                  "title": "Hidden, now back in stock",
                  "status": {{ hide_status | json }},
                  "tags": ["Lustre", {{ out_of_stock_tag | json }}],
                  "variantsCount": { "count": 1 },
                  "variants": { "nodes": [{ "inventoryQuantity": 3, "inventoryPolicy": "DENY", "inventoryItem": { "tracked": true } }] },
                  "since": { "value": {{ long_ago_s | append: "" | json }} },
                  "hiddenAt": { "value": {{ yesterday_s | append: "" | json }} }
                },
                {
                  "id": "gid://shopify/Product/4567890123",
                  "title": "Back in stock before hiding",
                  "status": "ACTIVE",
                  "tags": ["Lustre", {{ out_of_stock_tag | json }}],
                  "variantsCount": { "count": 1 },
                  "variants": { "nodes": [{ "inventoryQuantity": 2, "inventoryPolicy": "DENY", "inventoryItem": { "tracked": true } }] },
                  "since": { "value": {{ yesterday_s | append: "" | json }} },
                  "hiddenAt": null
                }
              ]
            }
          }
        }
      {% endcapture %}

      {% assign result = result_json | parse_json %}
    {% endif %}

    {% assign products = products | concat: result.data.products.nodes %}

    {% if result.data.products.pageInfo.hasNextPage %}
      {% assign cursor = result.data.products.pageInfo.endCursor %}
    {% else %}
      {% break %}
    {% endif %}
  {% endfor %}
{% endif %}

{% assign summary = hash %}
{% assign summary["tag"] = 0 %}
{% assign summary["hide"] = 0 %}
{% assign summary["restore"] = 0 %}
{% assign summary["untag"] = 0 %}

{% for product in products %}
  {% if product.status == "ARCHIVED" %}
    {% continue %}
  {% endif %}

  {% if product.variantsCount.count > product.variants.nodes.size %}
    {% log message: "Skipped: the product has more variants than this task checks.", product_id: product.id %}
    {% continue %}
  {% endif %}

  {% assign sellable = false %}

  {% for variant in product.variants.nodes %}
    {% if variant.inventoryPolicy == "CONTINUE" or variant.inventoryItem.tracked == false or variant.inventoryQuantity > 0 %}
      {% assign sellable = true %}
    {% endif %}
  {% endfor %}

  {% assign tagged = false %}
  {% assign never_hide = false %}
  {% assign our_tags = array %}
  {% assign other_tags = array %}

  {% for product_tag in product.tags %}
    {% assign product_tag_downcase = product_tag | downcase %}

    {% if product_tag_downcase == out_of_stock_tag_downcase %}
      {% assign tagged = true %}
      {% assign our_tags = our_tags | push: product_tag %}
    {% else %}
      {% assign other_tags = other_tags | push: product_tag %}
    {% endif %}

    {% if never_hide_tag != blank and product_tag_downcase == never_hide_tag_downcase %}
      {% assign never_hide = true %}
    {% endif %}
  {% endfor %}

  {% comment %}
    -- hiddenAt only counts when it is newer than since: older values belong to a previous out-of-stock spell
  {% endcomment %}

  {% assign since_s = nil %}
  {% assign hidden_this_spell = false %}

  {% if product.since %}
    {% assign since_s = product.since.value | date: "%s" | times: 1 %}

    {% if product.hiddenAt %}
      {% assign hidden_at_s = product.hiddenAt.value | date: "%s" | times: 1 %}

      {% if hidden_at_s >= since_s %}
        {% assign hidden_this_spell = true %}
      {% endif %}
    {% endif %}
  {% endif %}

  {% assign next_step = nil %}

  {% if sellable %}
    {% if tagged %}
      {% if hidden_this_spell and product.status != "ACTIVE" %}
        {% assign next_step = "restore" %}
      {% else %}
        {% assign next_step = "untag" %}
      {% endif %}
    {% endif %}

  {% elsif product.status == "ACTIVE" %}
    {% if tagged == false or since_s == nil %}
      {% assign next_step = "tag" %}

    {% elsif hidden_this_spell == false and never_hide == false %}
      {% comment %}
        -- hidden_this_spell on an active product means someone re-activated it by hand
      {% endcomment %}

      {% assign out_of_stock_for_s = now_s | minus: since_s %}

      {% if out_of_stock_for_s >= hide_after_s %}
        {% assign next_step = "hide" %}
      {% endif %}
    {% endif %}
  {% endif %}

  {% if next_step == nil %}
    {% continue %}
  {% endif %}

  {% unless allowed_steps contains next_step %}
    {% continue %}
  {% endunless %}

  {% assign summary[next_step] = summary[next_step] | plus: 1 %}

  {% if test_mode %}
    {% log would: next_step, product: product.title, product_id: product.id %}
    {% continue %}
  {% endif %}

  {% case next_step %}
    {% when "tag" %}
      {% assign new_tags = other_tags | push: out_of_stock_tag %}

      {% action "shopify" %}
        mutation {
          productUpdate(
            product: {
              id: {{ product.id | json }}
              tags: {{ new_tags | json }}
              metafields: [
                {
                  namespace: "mechanic"
                  key: "out_of_stock_since"
                  type: "date_time"
                  value: {{ current_time | json }}
                }
              ]
            }
          ) {
            product {
              id
              title
              status
            }
            userErrors {
              field
              message
            }
          }
        }
      {% endaction %}

    {% when "hide" %}
      {% action "shopify" %}
        mutation {
          productUpdate(
            product: {
              id: {{ product.id | json }}
              status: {{ hide_status }}
              metafields: [
                {
                  namespace: "mechanic"
                  key: "out_of_stock_hidden_at"
                  type: "date_time"
                  value: {{ current_time | json }}
                }
              ]
            }
          ) {
            product {
              id
              title
              status
            }
            userErrors {
              field
              message
            }
          }
        }
      {% endaction %}

    {% when "restore" %}
      {% action "shopify" %}
        mutation {
          productUpdate(
            product: {
              id: {{ product.id | json }}
              status: ACTIVE
              tags: {{ other_tags | json }}
            }
          ) {
            product {
              id
              title
              status
            }
            userErrors {
              field
              message
            }
          }
        }
      {% endaction %}

    {% when "untag" %}
      {% action "shopify" %}
        mutation {
          tagsRemove(
            id: {{ product.id | json }}
            tags: {{ our_tags | json }}
          ) {
            node {
              id
            }
            userErrors {
              field
              message
            }
          }
        }
      {% endaction %}
  {% endcase %}
{% endfor %}

{% unless event.topic == "shopify/inventory_levels/update" %}
  {% log summary: summary, test_mode: test_mode, products_scanned: products.size %}
{% endunless %}
